"""Build the bilingual Agentic AI flashcard bank from its maintainable source."""

import json
from pathlib import Path


# level, category_es, category_en, question_es, question_en, answer_es, answer_en
SEEDS = [
    ("Básico", "Fundamentos", "Foundations", "¿Qué distingue a un agente de IA de un chatbot que solo responde texto?", "What distinguishes an AI agent from a chatbot that only replies with text?", "Un agente puede perseguir un objetivo en un ciclo de observar, decidir y actuar usando herramientas; un chatbot simple solo genera respuestas.", "An agent can pursue a goal in an observe-decide-act loop using tools; a simple chatbot only generates replies."),
    ("Básico", "Fundamentos", "Foundations", "¿Qué es un modelo de lenguaje grande (LLM)?", "What is a large language model (LLM)?", "Un modelo entrenado con grandes corpus para predecir y generar secuencias de lenguaje; no es por sí solo un sistema de ingeniería autónomo.", "A model trained on large corpora to predict and generate language sequences; by itself it is not an autonomous engineering system."),
    ("Básico", "Fundamentos", "Foundations", "¿Qué es una herramienta (tool) para un agente?", "What is a tool for an agent?", "Una operación explícita y acotada —por ejemplo, leer un ticket o ejecutar pruebas— que el agente puede solicitar mediante una interfaz definida.", "An explicit, bounded operation—such as reading a ticket or running tests—that the agent can request through a defined interface."),
    ("Básico", "Fundamentos", "Foundations", "¿Qué es una llamada a herramienta (tool call)?", "What is a tool call?", "Una solicitud estructurada del modelo para ejecutar una herramienta con argumentos; el sistema ejecutor valida y devuelve el resultado al agente.", "A structured model request to execute a tool with arguments; the runtime validates it and returns the result to the agent."),
    ("Básico", "Fundamentos", "Foundations", "¿Qué función cumple el prompt de sistema de un agente?", "What is an agent's system prompt for?", "Define su rol, objetivos, límites, formato esperado y reglas de uso de herramientas; no reemplaza los controles técnicos de seguridad.", "It defines the agent's role, goals, boundaries, expected format, and tool-use rules; it does not replace technical security controls."),
    ("Básico", "Fundamentos", "Foundations", "¿Qué significa que un agente sea autónomo?", "What does it mean for an agent to be autonomous?", "Que puede realizar algunos pasos sin aprobación humana inmediata dentro de un alcance y permisos previamente definidos; no significa que deba tener acceso ilimitado.", "It can perform some steps without immediate human approval within predefined scope and permissions; it does not mean it should have unrestricted access."),
    ("Básico", "Fundamentos", "Foundations", "¿Qué es un ciclo de agente?", "What is an agent loop?", "La secuencia iterativa de recibir estado, razonar o elegir una acción, ejecutarla, revisar el resultado y continuar hasta completar o detenerse.", "The iterative sequence of receiving state, reasoning or choosing an action, executing it, reviewing the result, and continuing until completion or stop."),
    ("Básico", "Fundamentos", "Foundations", "¿Qué significa orquestar agentes?", "What does agent orchestration mean?", "Coordinar tareas, estado, herramientas, dependencias, límites y traspasos entre agentes para lograr un resultado verificable.", "Coordinating tasks, state, tools, dependencies, limits, and handoffs among agents to achieve a verifiable outcome."),
    ("Básico", "Fundamentos", "Foundations", "¿Qué es un agente especializado?", "What is a specialized agent?", "Un agente con una responsabilidad acotada, instrucciones, herramientas y criterios de salida adecuados a una tarea concreta, como análisis o revisión.", "An agent with a bounded responsibility, instructions, tools, and exit criteria suited to a specific task, such as analysis or review."),
    ("Básico", "Fundamentos", "Foundations", "¿Qué es el contexto de una tarea?", "What is task context?", "La información pertinente para completar una tarea: objetivo, criterios de aceptación, archivos, restricciones, decisiones previas y resultados de herramientas.", "The information relevant to completing a task: goal, acceptance criteria, files, constraints, prior decisions, and tool results."),
    ("Básico", "Fundamentos", "Foundations", "¿Qué es una ventana de contexto?", "What is a context window?", "El límite de tokens que un modelo puede procesar en una solicitud; obliga a seleccionar, resumir o recuperar contexto relevante.", "The token limit a model can process in a request; it makes selecting, summarizing, or retrieving relevant context necessary."),
    ("Básico", "Fundamentos", "Foundations", "¿Qué es la memoria de un agente?", "What is agent memory?", "Información persistida o recuperada entre pasos o sesiones para dar continuidad; debe tener alcance, retención y controles de privacidad definidos.", "Information persisted or retrieved across steps or sessions for continuity; its scope, retention, and privacy controls must be defined."),
    ("Básico", "Fundamentos", "Foundations", "¿Para qué se usa RAG?", "What is RAG used for?", "Retrieval-Augmented Generation busca documentos relevantes y los incorpora al contexto de generación para fundamentar respuestas en fuentes externas.", "Retrieval-Augmented Generation finds relevant documents and adds them to the generation context to ground answers in external sources."),
    ("Básico", "Fundamentos", "Foundations", "¿Qué es un flujo determinista frente a un agente?", "What is a deterministic workflow compared with an agent?", "Un flujo determinista ejecuta pasos y transiciones predefinidos; un agente elige entre acciones según el estado. Los sistemas robustos suelen combinar ambos.", "A deterministic workflow executes predefined steps and transitions; an agent chooses actions based on state. Robust systems often combine both."),
    ("Básico", "Fundamentos", "Foundations", "¿Qué significa humano en el circuito (human-in-the-loop)?", "What does human-in-the-loop mean?", "Que una persona revisa, aprueba o corrige pasos de riesgo o ambigüedad antes de permitir que el proceso continúe.", "A person reviews, approves, or corrects risky or ambiguous steps before allowing the process to continue."),
    ("Básico", "Fundamentos", "Foundations", "¿Qué es una salida estructurada?", "What is a structured output?", "Una respuesta ajustada a un esquema verificable —por ejemplo JSON validado— que facilita integración y comprobación automática.", "A response that conforms to a verifiable schema—such as validated JSON—to support integration and automated checking."),
    ("Básico", "Fundamentos", "Foundations", "¿Qué es una alucinación de un modelo?", "What is a model hallucination?", "Contenido inventado o incorrecto presentado con seguridad. Se mitiga con fuentes, validación, pruebas y límites de actuación, no solo con prompts.", "Invented or incorrect content presented confidently. It is mitigated with sources, validation, tests, and action limits—not prompts alone."),
    ("Básico", "Fundamentos", "Foundations", "¿Qué es un criterio de aceptación en una historia de usuario?", "What is an acceptance criterion in a user story?", "Una condición observable y comprobable que define cuándo una necesidad del usuario se considera satisfecha.", "An observable, testable condition that defines when a user need is considered satisfied."),
    ("Básico", "Fundamentos", "Foundations", "¿Qué significa mínimo privilegio para un agente?", "What does least privilege mean for an agent?", "Dar al agente solo los permisos y recursos indispensables para su tarea, con límites de alcance y duración.", "Giving an agent only the permissions and resources essential to its task, limited by scope and duration."),
    ("Básico", "Fundamentos", "Foundations", "¿Qué es una evaluación (eval) de un agente?", "What is an agent evaluation (eval)?", "Una medición repetible de calidad o seguridad sobre casos definidos, usando criterios y resultados esperados.", "A repeatable measurement of quality or safety on defined cases, using criteria and expected outcomes."),
    ("Intermedio", "Diseño de agentes", "Agent design", "¿Cuándo conviene usar varios agentes especializados en lugar de uno solo?", "When should you use multiple specialized agents instead of one?", "Cuando las tareas pueden separarse con contratos claros y la especialización mejora calidad, independencia o paralelismo más de lo que cuesta coordinar.", "When tasks can be separated with clear contracts and specialization improves quality, independence, or parallelism more than coordination costs."),
    ("Intermedio", "Diseño de agentes", "Agent design", "¿Qué problema resuelve el enrutamiento de agentes?", "What problem does agent routing solve?", "Selecciona el agente o flujo adecuado según tipo, estado, prioridad o riesgo de la tarea, evitando enviar todo a un agente genérico.", "It selects the appropriate agent or workflow based on task type, state, priority, or risk instead of sending everything to a generic agent."),
    ("Intermedio", "Diseño de agentes", "Agent design", "¿Qué es un contrato de salida entre agentes?", "What is an agent-to-agent output contract?", "Un esquema con campos obligatorios, restricciones, evidencia y estados de éxito o error que hace explícito qué entrega un agente al siguiente.", "A schema with required fields, constraints, evidence, and success or failure states that makes one agent's handoff explicit."),
    ("Intermedio", "Diseño de agentes", "Agent design", "¿Cómo descompondrías una historia grande para agentes?", "How would you decompose a large story for agents?", "Separando tareas por componentes y dependencias, preservando contratos de interfaz, criterios de aceptación y un responsable de integración.", "By separating tasks by component and dependency while preserving interface contracts, acceptance criteria, and an integration owner."),
    ("Intermedio", "Diseño de agentes", "Agent design", "¿Qué es una máquina de estados en un flujo de agentes?", "What is a state machine in an agent workflow?", "Un modelo explícito de estados válidos y transiciones —por ejemplo Ready, In Progress, Review, Failed— que controla qué acciones pueden ocurrir.", "An explicit model of valid states and transitions—such as Ready, In Progress, Review, Failed—that controls which actions may occur."),
    ("Intermedio", "Diseño de agentes", "Agent design", "¿Por qué conviene separar planificación y ejecución?", "Why separate planning from execution?", "Permite inspeccionar y aprobar el plan antes de acciones costosas o riesgosas, y limita que una salida no validada se convierta directamente en cambios.", "It lets people inspect and approve a plan before costly or risky actions and prevents unvalidated output from directly becoming changes."),
    ("Intermedio", "Diseño de agentes", "Agent design", "¿Qué debe contener un buen paquete de contexto para codificar?", "What should a good coding context package contain?", "Historia y criterios verificables, archivos relevantes, arquitectura y convenciones, restricciones, interfaces afectadas, pruebas y decisiones conocidas.", "The story and verifiable criteria, relevant files, architecture and conventions, constraints, affected interfaces, tests, and known decisions."),
    ("Intermedio", "Contexto y recuperación", "Context and retrieval", "¿Cómo limitarías el contexto recuperado para un ticket?", "How would you limit retrieved context for a ticket?", "Filtrando por repositorio, ruta, componente y actualidad; priorizando fuentes autorizadas y registrando referencias y versiones.", "Filter by repository, path, component, and recency; prioritize authoritative sources and record references and versions."),
    ("Intermedio", "Contexto y recuperación", "Context and retrieval", "¿Qué diferencia hay entre memoria de conversación y memoria de proyecto?", "What is the difference between conversation memory and project memory?", "La primera conserva el estado de una interacción; la segunda persiste conocimiento reutilizable del proyecto, con políticas de vigencia y acceso separadas.", "The first preserves an interaction's state; the second persists reusable project knowledge with separate freshness and access policies."),
    ("Intermedio", "Contexto y recuperación", "Context and retrieval", "¿Cómo verificarías que un resumen de ticket no perdió requisitos?", "How would you verify that a ticket summary did not lose requirements?", "Comparándolo contra criterios de aceptación y campos originales, conservando enlaces a fuentes y marcando explícitamente dudas o información ausente.", "Compare it against the original acceptance criteria and fields, preserve source links, and explicitly mark uncertainty or missing information."),
    ("Intermedio", "Jira y eventos", "Jira and events", "¿Qué evento puede iniciar el pipeline propuesto?", "What event can start the proposed pipeline?", "Una transición de Jira a In Progress o un evento equivalente, validado contra el proyecto, issue type y condiciones de elegibilidad.", "A Jira transition to In Progress or equivalent event, validated against project, issue type, and eligibility conditions."),
    ("Intermedio", "Jira y eventos", "Jira and events", "¿Qué debe hacer el agente de contexto antes de codificar?", "What should the context agent do before coding?", "Leer la historia y documentación pertinente, detectar ambigüedad, producir un paquete de contexto con criterios comprobables y solicitar aclaración si falta información crítica.", "Read the story and relevant documentation, detect ambiguity, produce a context package with testable criteria, and request clarification if critical information is missing."),
    ("Intermedio", "Jira y eventos", "Jira and events", "¿Qué papel podría tener Atlassian Rovo en el pipeline?", "What role could Atlassian Rovo play in the pipeline?", "Puede apoyar búsqueda y síntesis de conocimiento de Atlassian según las capacidades y permisos disponibles; las acciones de escritura/despliegue requieren controles explícitos.", "It can support search and synthesis of Atlassian knowledge according to available capabilities and permissions; write or deploy actions need explicit controls."),
    ("Intermedio", "Jira y eventos", "Jira and events", "¿Por qué no basta con confiar en una notificación de webhook de Jira?", "Why is trusting a Jira webhook notification not enough?", "Puede repetirse, llegar tarde o fallar; valida autenticidad, vuelve a consultar el estado actual y procesa idempotentemente.", "It can be duplicated, delayed, or fail; validate authenticity, re-fetch current state, and process idempotently."),
    ("Intermedio", "Jira y eventos", "Jira and events", "¿Qué es idempotencia en un consumidor de eventos?", "What is idempotency in an event consumer?", "Procesar varias veces el mismo evento produce el mismo efecto que procesarlo una sola vez, normalmente usando una clave de deduplicación persistida.", "Processing the same event multiple times has the same effect as processing it once, typically using a persisted deduplication key."),
    ("Intermedio", "Jira y eventos", "Jira and events", "¿Cómo evitarías ejecutar dos pipelines para el mismo ticket?", "How would you prevent two pipelines from running for the same ticket?", "Usa una clave idempotente por issue y transición, un bloqueo o lease con vencimiento y una comprobación del estado antes de iniciar.", "Use an idempotency key per issue and transition, a lock or expiring lease, and a state check before starting."),
    ("Intermedio", "Ejecución y estado", "Execution and state", "¿Qué diferencia hay entre reintentar y reiniciar un workflow?", "What is the difference between retrying and restarting a workflow?", "Un reintento repite una operación fallida de forma controlada; reiniciar puede duplicar efectos. Ambos requieren estado, límites y seguridad idempotente.", "A retry repeats a failed operation in a controlled way; a restart may duplicate effects. Both require state, limits, and idempotency safety."),
    ("Intermedio", "Ejecución y estado", "Execution and state", "¿Qué es un checkpoint en un workflow?", "What is a checkpoint in a workflow?", "Un estado durable guardado en un límite seguro que permite reanudar, inspeccionar o recuperar el proceso sin repetir todos los pasos.", "A durable state saved at a safe boundary that allows the process to resume, inspect, or recover without repeating every step."),
    ("Intermedio", "Ejecución y estado", "Execution and state", "¿Qué es un límite de iteraciones para un agente?", "What is an agent iteration limit?", "Un máximo de pasos o tiempo que impide ciclos interminables y acota costo; al alcanzarse debe producir un estado recuperable o pedir intervención.", "A maximum number of steps or duration that prevents endless loops and bounds cost; on reaching it, the agent should return a recoverable state or ask for intervention."),
    ("Intermedio", "Ejecución y estado", "Execution and state", "¿Cómo pueden trabajar en paralelo los agentes de código y pruebas?", "How can coding and test agents work in parallel?", "El agente de pruebas puede derivar casos de criterios y contratos mientras el agente de código implementa; ambos trabajan en ramas o espacios aislados y sincronizan antes de ejecutar la suite final.", "The test agent can derive cases from criteria and contracts while the coding agent implements; both work in isolated branches or workspaces and synchronize before the final suite."),
    ("Intermedio", "Ejecución y estado", "Execution and state", "¿Por qué no debería el agente de pruebas editar los mismos archivos del agente de código?", "Why should the test agent not edit the same files as the coding agent?", "La escritura simultánea genera conflictos y resultados no deterministas; define propiedad de archivos, interfaces y una fase de integración.", "Concurrent writes cause conflicts and nondeterministic results; define file ownership, interfaces, and an integration phase."),
    ("Intermedio", "Pruebas de software", "Software testing", "¿Qué diferencia una prueba unitaria de una de integración?", "What distinguishes a unit test from an integration test?", "La unitaria aísla una unidad con dependencias sustituidas; la de integración comprueba colaboraciones reales entre componentes o sistemas.", "A unit test isolates a unit with replaced dependencies; an integration test checks real collaboration between components or systems."),
    ("Intermedio", "Pruebas de software", "Software testing", "¿Qué valida una prueba funcional?", "What does a functional test validate?", "Que un comportamiento del sistema cumpla requisitos o criterios de aceptación desde una perspectiva observable, a menudo a través de interfaces representativas.", "That system behavior meets requirements or acceptance criteria from an observable perspective, often through representative interfaces."),
    ("Intermedio", "Pruebas de software", "Software testing", "¿Qué son pruebas basadas en criterios de aceptación?", "What are acceptance-criteria-based tests?", "Casos trazables a cada condición de la historia, con entradas, acción y resultado esperado, incluidos casos negativos relevantes.", "Cases traceable to each story condition, with inputs, action, and expected result, including relevant negative cases."),
    ("Intermedio", "Pruebas de software", "Software testing", "¿Qué debe entregar un agente de pruebas además del código de pruebas?", "What should a test agent deliver besides test code?", "Mapa de trazabilidad a criterios, comandos ejecutados, resultados, cobertura significativa y limitaciones o casos no ejecutables.", "A traceability map to criteria, commands run, results, meaningful coverage, and limitations or cases that could not run."),
    ("Intermedio", "Pruebas de software", "Software testing", "¿Cómo evitar que las pruebas generadas solo confirmen la implementación actual?", "How do you prevent generated tests from only confirming the current implementation?", "Deriva oráculos de requisitos independientes, diseña casos límite y negativos, y revisa mutaciones o ejemplos que deberían fallar.", "Derive oracles independently from requirements, design boundary and negative cases, and review mutations or examples that should fail."),
    ("Intermedio", "Pruebas de software", "Software testing", "¿Qué hacer si el agente de pruebas detecta una regresión antes de terminar el agente de código?", "What should happen if the test agent finds a regression before the coding agent finishes?", "Reportar hallazgo con evidencia al agente de código, conservar un caso reproducible y volver a ejecutar pruebas cuando haya un cambio relevante.", "Report the finding with evidence to the coding agent, preserve a reproducible case, and rerun tests after a relevant change."),
    ("Intermedio", "Revisión y entrega", "Review and delivery", "¿Qué debe revisar un agente de code review?", "What should a code-review agent inspect?", "Correctitud contra criterios, regresiones, seguridad, manejo de errores, mantenibilidad y pruebas; debe señalar archivo/línea y evidencia, no solo aprobar por estilo.", "Correctness against criteria, regressions, security, error handling, maintainability, and tests; it should cite file/line and evidence, not approve based only on style."),
    ("Intermedio", "Revisión y entrega", "Review and delivery", "¿Cómo debe tratar el pipeline una revisión con hallazgos críticos?", "How should the pipeline handle a review with critical findings?", "Bloquear la transición o merge, devolver hallazgos accionables al agente de código y exigir revisión posterior con evidencia de corrección.", "Block the transition or merge, return actionable findings to the coding agent, and require a follow-up review with correction evidence."),
    ("Intermedio", "Revisión y entrega", "Review and delivery", "¿Qué hace CI en un pipeline de ingeniería?", "What does CI do in an engineering pipeline?", "Integra cambios y ejecuta verificaciones automatizadas como lint, compilación, pruebas y análisis de seguridad antes de aceptar el cambio.", "It integrates changes and runs automated checks such as lint, build, tests, and security analysis before accepting the change."),
    ("Intermedio", "Revisión y entrega", "Review and delivery", "¿Qué diferencia hay entre entrega continua y despliegue continuo?", "What is the difference between continuous delivery and continuous deployment?", "La entrega continua deja una versión validada lista para liberar con aprobación; el despliegue continuo publica automáticamente si se satisfacen las puertas de calidad.", "Continuous delivery keeps a validated release ready for approval; continuous deployment releases automatically when quality gates pass."),
    ("Intermedio", "Revisión y entrega", "Review and delivery", "¿Qué significa una puerta de calidad en CI/CD?", "What is a quality gate in CI/CD?", "Una condición automática —por ejemplo, pruebas requeridas aprobadas y cero vulnerabilidades críticas— que debe cumplirse antes de avanzar.", "An automated condition—such as required tests passing and no critical vulnerabilities—that must be met before proceeding."),
    ("Intermedio", "Revisión y entrega", "Review and delivery", "¿Por qué el code review no debe ser la única puerta antes del despliegue?", "Why should code review not be the only gate before deployment?", "La revisión puede omitir fallos reproducibles; se complementa con pruebas, análisis estático, controles de dependencias y aprobación para entornos de riesgo.", "Review can miss reproducible failures; it should be combined with tests, static analysis, dependency controls, and approval for risky environments."),
    ("Intermedio", "Integración", "Integration", "¿Qué es MCP y cómo ayuda en un sistema de agentes?", "What is MCP and how can it help an agent system?", "Model Context Protocol define una forma interoperable de exponer herramientas y recursos a modelos; cada servidor MCP debe tratarse como una frontera de confianza.", "Model Context Protocol defines an interoperable way to expose tools and resources to models; each MCP server should be treated as a trust boundary."),
    ("Intermedio", "Integración", "Integration", "¿Qué significa A2A en sistemas de agentes?", "What does A2A mean in agent systems?", "Agent-to-Agent describe patrones o protocolos de comunicación y delegación entre agentes; no reemplaza contratos, autorización ni validación.", "Agent-to-Agent describes patterns or protocols for communication and delegation between agents; it does not replace contracts, authorization, or validation."),
    ("Intermedio", "Evaluación y observabilidad", "Evaluation and observability", "¿Qué es una traza distribuida de un pipeline multiagente?", "What is a distributed trace for a multi-agent pipeline?", "Un registro correlacionado del recorrido de un ticket por eventos, agentes, herramientas, llamadas, pruebas y decisiones, con tiempos y resultados.", "A correlated record of a ticket's path through events, agents, tools, calls, tests, and decisions, with timing and outcomes."),
    ("Intermedio", "Evaluación y observabilidad", "Evaluation and observability", "¿Qué métricas medirías para un pipeline de agentes?", "What metrics would you measure for an agent pipeline?", "Tasa de éxito por etapa, tiempo de ciclo, reintentos, fallos, hallazgos aceptados, defectos escapados, costo/token y frecuencia de aprobación humana.", "Stage success rate, cycle time, retries, failures, accepted findings, escaped defects, cost/tokens, and human-approval frequency."),
    ("Intermedio", "Evaluación y observabilidad", "Evaluation and observability", "¿Por qué registrar las versiones de prompts y modelos?", "Why record prompt and model versions?", "Para reproducir decisiones, explicar cambios de comportamiento y comparar evaluaciones a través de despliegues.", "To reproduce decisions, explain behavior changes, and compare evaluations across deployments."),
    ("Intermedio", "Evaluación y observabilidad", "Evaluation and observability", "¿Qué es un conjunto de regresión de agentes?", "What is an agent regression set?", "Una colección versionada de casos representativos con resultados o criterios esperados que se vuelve a ejecutar al cambiar prompt, modelo, herramienta o workflow.", "A versioned collection of representative cases with expected outcomes or criteria, rerun when prompts, models, tools, or workflows change."),
    ("Avanzado", "Arquitectura de orquestación", "Orchestration architecture", "¿Cómo diseñarías el límite entre lógica determinista y decisiones del LLM?", "How would you design the boundary between deterministic logic and LLM decisions?", "Usa código y máquina de estados para permisos, transiciones, validación y efectos externos; reserva el LLM para clasificación o propuestas con salida estructurada y verificable.", "Use code and a state machine for permissions, transitions, validation, and external side effects; reserve the LLM for classification or proposals with structured, verifiable output."),
    ("Avanzado", "Arquitectura de orquestación", "Orchestration architecture", "¿Cuándo elegirías un grafo durable frente a una cadena lineal de prompts?", "When would you choose a durable graph over a linear prompt chain?", "Cuando hay bifurcaciones, paralelismo, reintentos, estado persistente, pausas de aprobación o recuperación que deben ser observables y reproducibles.", "When branching, parallelism, retries, persistent state, approval pauses, or recovery must be observable and reproducible."),
    ("Avanzado", "Arquitectura de orquestación", "Orchestration architecture", "¿Cómo modelarías el estado durable de una tarea de ingeniería?", "How would you model durable state for an engineering task?", "Persistiría ID de issue, versión de entrada, estado, artefactos/commit, decisiones, resultados de pruebas, aprobaciones, intentos y marcas de tiempo con transiciones auditables.", "Persist the issue ID, input version, state, artifacts/commit, decisions, test results, approvals, attempts, and timestamps with auditable transitions."),
    ("Avanzado", "Arquitectura de orquestación", "Orchestration architecture", "¿Cómo evitar la condición de carrera entre transición de Jira y recepción del webhook?", "How do you avoid a race between a Jira transition and webhook delivery?", "Tras validar la firma, consulta Jira por el estado y versión actual; usa deduplicación y una transición condicional en vez de confiar en el orden de entrega.", "After validating the signature, query Jira for its current state and version; use deduplication and a conditional transition instead of trusting delivery order."),
    ("Avanzado", "Arquitectura de orquestación", "Orchestration architecture", "¿Qué estrategia usarías para eventos perdidos o duplicados?", "What strategy would you use for lost or duplicated events?", "Patrón inbox/outbox o cola durable, clave idempotente, reintento con backoff, cola de fallos y reconciliación periódica con el sistema fuente.", "A durable inbox/outbox or queue, idempotency key, backoff retries, dead-letter queue, and periodic reconciliation with the source system."),
    ("Avanzado", "Arquitectura de orquestación", "Orchestration architecture", "¿Cómo coordinar tareas paralelas sin perder consistencia?", "How do you coordinate parallel tasks without losing consistency?", "Define dependencias y contratos, fija una versión base, aísla escrituras, sincroniza resultados en puntos de unión y valida el conjunto integrado antes de avanzar.", "Define dependencies and contracts, pin a base version, isolate writes, synchronize results at join points, and validate the integrated whole before proceeding."),
    ("Avanzado", "Arquitectura de orquestación", "Orchestration architecture", "¿Qué riesgo presenta un agente que modifica Jira y Git en la misma operación?", "What risk does an agent that modifies Jira and Git in one operation create?", "No hay transacción atómica entre sistemas; una operación puede completarse parcialmente. Se requieren pasos compensatorios, reconciliación y registro de efectos.", "There is no atomic transaction across systems; an operation can partially complete. Compensating steps, reconciliation, and effect logging are needed."),
    ("Avanzado", "Arquitectura de orquestación", "Orchestration architecture", "¿Cómo manejarías una cancelación de ticket mientras corren agentes?", "How would you handle a ticket cancellation while agents are running?", "Propaga una señal de cancelación al workflow, detén nuevos efectos, cancela tareas cooperativamente, marca artefactos parciales y reconcilia el estado con Jira.", "Propagate a cancellation signal through the workflow, stop new side effects, cooperatively cancel tasks, mark partial artifacts, and reconcile Jira state."),
    ("Avanzado", "Arquitectura de orquestación", "Orchestration architecture", "¿Cómo establecerías límites de costo y latencia por ticket?", "How would you set per-ticket cost and latency limits?", "Presupuestos por etapa y ticket para tokens, llamadas y tiempo; alertas y corte al excederlos, con salida parcial y ruta de escalamiento.", "Per-stage and per-ticket budgets for tokens, calls, and time; alert and stop on overrun, with partial output and an escalation path."),
    ("Avanzado", "Arquitectura de orquestación", "Orchestration architecture", "¿Cómo elegirías un modelo de respaldo si falla el modelo principal?", "How would you choose a fallback model if the primary fails?", "Verifica compatibilidad de herramientas y calidad con evaluaciones, limita el fallback a fallos transitorios y registra el modelo usado; no cambies silenciosamente en pasos de alto riesgo.", "Verify tool compatibility and quality with evaluations, limit fallback to transient failures, and record the model used; do not silently switch for high-risk steps."),
    ("Avanzado", "Seguridad de agentes", "Agent security", "¿Qué es una inyección indirecta de prompt en un agente de codificación?", "What is indirect prompt injection in a coding agent?", "Instrucciones maliciosas ocultas en contenido recuperado —como un issue o README— que intentan cambiar el comportamiento del agente; el contenido externo debe tratarse como datos no confiables.", "Malicious instructions hidden in retrieved content—such as an issue or README—that try to change agent behavior; external content must be treated as untrusted data."),
    ("Avanzado", "Seguridad de agentes", "Agent security", "¿Por qué las instrucciones del ticket no pueden otorgar permisos al agente?", "Why can't ticket instructions grant permissions to an agent?", "El ticket es entrada no confiable; los permisos se definen fuera del prompt por políticas de identidad, autorización y herramientas.", "The ticket is untrusted input; permissions are defined outside the prompt by identity, authorization, and tool policies."),
    ("Avanzado", "Seguridad de agentes", "Agent security", "¿Cómo reducirías el riesgo de exfiltración de secretos por un agente?", "How would you reduce an agent's risk of secret exfiltration?", "No expongas secretos en el contexto, usa credenciales de corta duración y alcance mínimo, redacta logs, limita salida de red y audita cada acceso.", "Keep secrets out of context, use short-lived least-scope credentials, redact logs, restrict outbound networking, and audit every access."),
    ("Avanzado", "Seguridad de agentes", "Agent security", "¿Qué controles aplicarías al ejecutar código generado por un agente?", "What controls would you apply when running agent-generated code?", "Ejecución en sandbox efímero sin credenciales, red restringida, recursos limitados, dependencias controladas y destrucción del entorno al terminar.", "Run in an ephemeral sandbox without credentials, with restricted networking, resource limits, controlled dependencies, and environment teardown afterward."),
    ("Avanzado", "Seguridad de agentes", "Agent security", "¿Qué debe cubrir el modelo de amenazas de un pipeline multiagente?", "What should a multi-agent pipeline threat model cover?", "Activos, identidades, fronteras de confianza, prompt injection, herramientas, cadena de suministro, secretos, abuso de permisos, resultados maliciosos y recuperación.", "Assets, identities, trust boundaries, prompt injection, tools, supply chain, secrets, permission abuse, malicious outputs, and recovery."),
    ("Avanzado", "Seguridad de agentes", "Agent security", "¿Cómo separarías los permisos de lectura y escritura del agente de contexto?", "How would you separate read and write permissions for the context agent?", "Dale acceso de solo lectura a Jira, repositorios y documentos; emite su propuesta como artefacto y deja las transiciones o comentarios a un actor controlado aparte.", "Give it read-only access to Jira, repositories, and documents; emit its proposal as an artifact and leave transitions or comments to a separate controlled actor."),
    ("Avanzado", "Seguridad de agentes", "Agent security", "¿Qué significa aprobación humana basada en riesgo?", "What does risk-based human approval mean?", "Exigir aprobación para acciones de alto impacto —como merge, acceso a producción o cambios de datos— y permitir automatización de bajo riesgo bajo políticas comprobables.", "Require approval for high-impact actions—such as merge, production access, or data changes—while allowing low-risk automation under verifiable policies."),
    ("Avanzado", "Seguridad de agentes", "Agent security", "¿Qué evidencia debe quedar antes de permitir un despliegue?", "What evidence should exist before allowing a deployment?", "Commit revisado, resultados de CI, pruebas vinculadas a requisitos, escaneos, artefacto identificado, aprobaciones requeridas y registro de quién o qué autorizó.", "Reviewed commit, CI results, requirement-linked tests, scans, identified artifact, required approvals, and a record of who or what authorized it."),
    ("Avanzado", "Pruebas y calidad", "Testing and quality", "¿Cómo pruebas un agente cuya salida es no determinista?", "How do you test an agent with nondeterministic output?", "Usa conjuntos de evaluación con rúbricas o aserciones invariantes, repeticiones para estimar variabilidad y pruebas de seguridad; no compares solo cadenas exactas.", "Use evaluation sets with rubrics or invariant assertions, repeated runs to estimate variance, and safety tests; do not rely only on exact string comparisons."),
    ("Avanzado", "Pruebas y calidad", "Testing and quality", "¿Qué es una prueba de contrato entre agentes?", "What is a contract test between agents?", "Verifica que las salidas de un agente cumplan el esquema y semántica esperados por el siguiente, incluyendo errores, campos ausentes y versiones incompatibles.", "It verifies that one agent's outputs meet the next agent's expected schema and semantics, including errors, missing fields, and incompatible versions."),
    ("Avanzado", "Pruebas y calidad", "Testing and quality", "¿Qué aporta el testing basado en propiedades a herramientas de agentes?", "What does property-based testing add for agent tools?", "Genera muchas entradas y verifica invariantes —por ejemplo, validación de rutas o idempotencia— para descubrir casos límite no escritos a mano.", "It generates many inputs and checks invariants—such as path validation or idempotency—to uncover edge cases not written by hand."),
    ("Avanzado", "Pruebas y calidad", "Testing and quality", "¿Cómo evitar fuga de datos entre tickets al reutilizar memoria?", "How do you prevent data leakage between tickets when reusing memory?", "Aísla la memoria por tenant/proyecto y permisos, filtra cada recuperación por ACL y evita incorporar datos sensibles de una tarea a otra.", "Isolate memory by tenant/project and permissions, filter every retrieval by ACL, and prevent sensitive data from one task entering another."),
    ("Avanzado", "Pruebas y calidad", "Testing and quality", "¿Qué es una métrica de defectos escapados y por qué importa?", "What is an escaped-defect metric and why does it matter?", "Cuenta defectos detectados después de la puerta prevista; revela si las pruebas, revisión o evaluación del agente realmente previenen fallos en producción.", "It counts defects found after the intended gate; it shows whether agent evaluation, tests, or review actually prevent production failures."),
    ("Avanzado", "Pruebas y calidad", "Testing and quality", "¿Cómo distinguirías una evaluación de modelo de una prueba de software convencional?", "How would you distinguish a model evaluation from a conventional software test?", "La prueba convencional suele verificar comportamiento determinista de código; la evaluación de modelo mide calidad probabilística según rúbricas, distribución de casos y umbrales de aceptación.", "A conventional test often checks deterministic code behavior; a model evaluation measures probabilistic quality using rubrics, case distributions, and acceptance thresholds."),
    ("Avanzado", "Pruebas y calidad", "Testing and quality", "¿Cuándo usarías pruebas de mutación en las pruebas generadas?", "When would you use mutation testing for generated tests?", "Para comprobar si la suite detecta cambios erróneos intencionales; si los mutantes sobreviven, las aserciones pueden ser débiles o no reflejar requisitos.", "To check whether the suite catches intentional faulty changes; surviving mutants may indicate weak assertions or tests disconnected from requirements."),
    ("Avanzado", "Pruebas y calidad", "Testing and quality", "¿Cómo establecerías un criterio de salida para el agente de pruebas?", "How would you define an exit criterion for the test agent?", "Todos los criterios trazables cubiertos o marcados como bloqueados, comandos ejecutados reportados, fallos clasificados y sin fallos críticos sin resolver.", "All criteria traced as covered or blocked, commands reported, failures classified, and no unresolved critical failures."),
    ("Avanzado", "Confiabilidad y distribución", "Reliability and distribution", "¿Qué hace una cola de fallos (dead-letter queue) en este pipeline?", "What does a dead-letter queue do in this pipeline?", "Aísla eventos que agotaron reintentos para inspección y reproceso controlado sin bloquear el resto del flujo.", "It isolates events that exhausted retries for inspection and controlled replay without blocking the rest of the workflow."),
    ("Avanzado", "Confiabilidad y distribución", "Reliability and distribution", "¿Por qué usar backoff exponencial con jitter?", "Why use exponential backoff with jitter?", "Espacia reintentos aumentando el intervalo y agrega variación para evitar que muchos workers reintenten juntos y sobrecarguen un servicio recuperándose.", "It spaces retries with increasing intervals and adds randomness so many workers do not retry together and overload a recovering service."),
    ("Avanzado", "Confiabilidad y distribución", "Reliability and distribution", "¿Qué es un patrón saga aplicado a Jira, Git y CI?", "What is a saga pattern applied to Jira, Git, and CI?", "Una secuencia de efectos locales con pasos compensatorios o reconciliación, porque no existe una transacción única que abarque los tres sistemas.", "A sequence of local effects with compensating steps or reconciliation, because no single transaction spans all three systems."),
    ("Avanzado", "Confiabilidad y distribución", "Reliability and distribution", "¿Cómo asegurarías orden por ticket sin serializar todos los tickets?", "How would you ensure per-ticket ordering without serializing every ticket?", "Particiona o bloquea por issue ID, manteniendo orden dentro de cada issue mientras tickets independientes se procesan en paralelo.", "Partition or lock by issue ID, preserving order within each issue while independent tickets run in parallel."),
    ("Avanzado", "Confiabilidad y distribución", "Reliability and distribution", "¿Qué es backpressure en un sistema de agentes?", "What is backpressure in an agent system?", "Un mecanismo para limitar o ralentizar la admisión cuando etapas posteriores están saturadas, evitando acumulación ilimitada y degradación en cascada.", "A mechanism to limit or slow intake when downstream stages are saturated, preventing unbounded queues and cascading degradation."),
    ("Avanzado", "Confiabilidad y distribución", "Reliability and distribution", "¿Cómo manejarías una caída temporal del proveedor de modelos?", "How would you handle a temporary model-provider outage?", "Aplica timeout y circuit breaker, reintento limitado con backoff, fallback previamente evaluado o pausa durable con alerta; evita repetir efectos externos.", "Apply timeouts and a circuit breaker, bounded backoff retries, a pre-evaluated fallback, or a durable pause with alerting; avoid repeating external side effects."),
    ("Avanzado", "Confiabilidad y distribución", "Reliability and distribution", "¿Cómo evitar que un agente mantenga un bloqueo de ticket indefinidamente?", "How do you prevent an agent from holding a ticket lock indefinitely?", "Usa leases con expiración, renovación condicionada al estado del workflow y recuperación de tareas huérfanas.", "Use expiring leases, renew them only while workflow state permits, and recover orphaned tasks."),
    ("Avanzado", "Confiabilidad y distribución", "Reliability and distribution", "¿Qué indicadores usarías para definir un SLO del pipeline?", "What indicators would you use to define a pipeline SLO?", "Porcentaje de tickets elegibles completados dentro de un tiempo objetivo, tasa de éxito seguro por etapa y disponibilidad de las puertas críticas, medidos sobre una ventana definida.", "The share of eligible tickets completed within a target time, safe per-stage success rate, and availability of critical gates over a defined window."),
    ("Avanzado", "Entrega y gobernanza", "Delivery and governance", "¿Qué diferencia hay entre aprobar un PR y autorizar un despliegue a producción?", "What is the difference between approving a PR and authorizing a production deployment?", "El PR acepta un cambio para integrar; producción es una acción de impacto distinta que puede requerir evidencia, aprobaciones, estrategia de rollout y capacidad de rollback.", "PR approval accepts a change for integration; production is a separate high-impact action that may require evidence, approvals, rollout strategy, and rollback capability."),
    ("Avanzado", "Entrega y gobernanza", "Delivery and governance", "¿Cómo separarías la generación del artefacto y su despliegue?", "How would you separate artifact creation from deployment?", "Construye una vez un artefacto inmutable identificado por digest, verifica y promueve ese mismo artefacto entre entornos con aprobaciones apropiadas.", "Build one immutable artifact identified by digest, verify it, and promote that same artifact across environments with appropriate approvals."),
    ("Avanzado", "Entrega y gobernanza", "Delivery and governance", "¿Qué es una estrategia canary y cómo encaja con un despliegue automatizado?", "What is a canary strategy and how does it fit automated deployment?", "Expone gradualmente una versión a una fracción del tráfico, observa SLI y revierte o detiene si excede umbrales definidos.", "It gradually exposes a version to a fraction of traffic, observes SLIs, and rolls back or stops if defined thresholds are exceeded."),
    ("Avanzado", "Entrega y gobernanza", "Delivery and governance", "¿Cómo diseñarías rollback de una versión desplegada por un agente?", "How would you design rollback for an agent-deployed release?", "Usa artefactos versionados, migraciones compatibles hacia atrás, estrategia automática basada en salud y autorización explícita; registra quién inició y completó el rollback.", "Use versioned artifacts, backward-compatible migrations, health-based automated strategy, and explicit authorization; record who initiated and completed rollback."),
    ("Avanzado", "Entrega y gobernanza", "Delivery and governance", "¿Qué evidencias de procedencia (provenance) conservarías?", "What provenance evidence would you retain?", "Relación entre ticket, contexto y fuentes, commit, versiones de modelos/prompts, acciones de herramientas, evaluaciones, aprobación, artefacto y despliegue.", "The links between ticket, context and sources, commit, model/prompt versions, tool actions, evaluations, approvals, artifact, and deployment."),
    ("Avanzado", "Entrega y gobernanza", "Delivery and governance", "¿Cómo harías auditable una decisión autónoma del agente?", "How would you make an autonomous agent decision auditable?", "Registra entradas referenciadas, política aplicada, salida estructurada, herramientas llamadas, identidad, versiones y resultado, minimizando datos sensibles.", "Record referenced inputs, applied policy, structured output, tools called, identity, versions, and outcome while minimizing sensitive data."),
    ("Avanzado", "Entrega y gobernanza", "Delivery and governance", "¿Qué significa segregación de funciones en un pipeline agentic?", "What does separation of duties mean in an agentic pipeline?", "Que quien propone o implementa un cambio no sea la única identidad que lo valida y despliega; aplica controles de aprobación independientes según riesgo.", "The identity proposing or implementing a change is not the only one validating and deploying it; apply independent approval controls according to risk."),
]


def main() -> None:
    destination = Path(__file__).resolve().parents[1] / "docs" / "data" / "question_bank.json"
    questions = []
    for index, (level, category_es, category_en, q_es, q_en, a_es, a_en) in enumerate(SEEDS, 1):
        questions.append({
            "id": f"AG-{index:03}",
            "level": {"es": level, "en": {"Básico": "Basic", "Intermedio": "Intermediate", "Avanzado": "Advanced"}[level]},
            "category": {"es": category_es, "en": category_en},
            "question": {"es": q_es, "en": q_en},
            "answer": {"es": a_es, "en": a_en},
            "explanation": {"es": a_es, "en": a_en},
        })
    destination.parent.mkdir(parents=True, exist_ok=True)
    destination.write_text(json.dumps(questions, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"Generadas {len(questions)} preguntas bilingües en {destination}")


if __name__ == "__main__":
    main()
